UPDATE patients p
INNER JOIN (
  SELECT patientId, MAX(startsAt) AS lastVisitAt
  FROM appointments
  WHERE tenantId = '01HQCFPUB0000000000000001' AND deletedAt IS NULL
  GROUP BY patientId
) a ON a.patientId = p.id
SET p.lastVisitAt = a.lastVisitAt, p.updatedAt = 1704067200000, p.updatedBy = '01HQCFPUB0000000000000004'
WHERE p.tenantId = '01HQCFPUB0000000000000001' AND p.deletedAt IS NULL;
